$ok=0; $skip=0; $miss=@()
$i=0
foreach ($e in $list) {
  $i++
  $src = Join-Path $root $e[1]
  $dir = Join-Path $dst $e[0]
  if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  $name = Split-Path $e[1] -Leaf
  $to = Join-Path $dir $name
  if (-not (Test-Path -LiteralPath $src)) { $miss += $e[1]; continue }
  if (Test-Path -LiteralPath $to) { $skip++; continue }
  try { Copy-Item -LiteralPath $src -Destination $to -ErrorAction Stop; $ok++ } catch { $miss += ($e[1] + "  (" + $_.Exception.Message + ")") }
  Write-Progress -Activity "Копирую книги" -Status "$i из $($list.Count)" -PercentComplete ($i*100/$list.Count)
}
Write-Host ""
Write-Host "ГОТОВО. Скопировано: $ok, уже были: $skip, не найдено: $($miss.Count)" -ForegroundColor Green
if ($miss.Count) { $miss | Set-Content -LiteralPath (Join-Path $dst "_не_найдено.txt") -Encoding UTF8; $miss | ForEach-Object { Write-Host " - $_" } }
explorer.exe $dst
